window.__TNPSC_REGISTER_TEST__("tamil", 6, [{"id":501,"subject":"tamil","testNumber":6,"question":"எட்டுத்தொகை நூல்களுள் அகமும் புறமும் கலந்த ஒரே நூல் எது?","options":["பதிற்றுப்பத்து","குறுந்தொகை","பரிபாடல்","கலித்தொகை"],"correctAnswer":2,"explanation":"எட்டுத்தொகை நூல்களுள் நற்றிணை, குறுந்தொகை, ஐங்குறுநூறு, கலித்தொகை, அகநானூறு ஆகிய ஐந்தும் அகநூல்கள்; பதிற்றுப்பத்து, புறநானூறு ஆகிய இரண்டும் புறநூல்கள். பரிபாடல் மட்டுமே அகமும் புறமும் கலந்த நூலாக விளங்குகிறது.","difficulty":"easy","topic":"எட்டுத்தொகை – பொது அறிமுகம்"},{"id":502,"subject":"tamil","testNumber":6,"question":"எட்டுத்தொகை நூல்களுள் 'நல்' என்ற அடைமொழியுடன் சிறப்பிக்கப்படும் நூல் எது?","options":["அகநானூறு","குறுந்தொகை","ஐங்குறுநூறு","நற்றிணை"],"correctAnswer":3,"explanation":"எட்டுத்தொகை நூல்களைக் கூறும் பழம்பாடலில் 'நற்றிணை நல்ல குறுந்தொகை ஐங்குறுநூறு' எனக் குறிப்பிடப்படுகிறது. இதில் 'நல்' என்ற அடைமொழி பெற்ற நூல் நற்றிணையாகும்; 'நல்ல' என்ற அடைமொழி குறுந்தொகைக்கு உரியது.","difficulty":"easy","topic":"எட்டுத்தொகை – நற்றிணை"},{"id":503,"subject":"tamil","testNumber":6,"question":"'நல்ல' என்ற அடைமொழியால் போற்றப்படும் எட்டுத்தொகை நூல் எது?","options":["பரிபாடல்","நற்றிணை","குறுந்தொகை","புறநானூறு"],"correctAnswer":2,"explanation":"குறுந்தொகை 'நல்ல குறுந்தொகை' என்ற அடைமொழியுடன் சிறப்பிக்கப்படுகிறது. நான்கு முதல் எட்டு அடிகள் வரையிலான எல்லைக்குள் அமைந்த நானூறு அகப்பொருள் பாடல்களைக் கொண்டதால் இதற்குக் குறுந்தொகை எனப் பெயர் ஏற்பட்டது.","difficulty":"easy","topic":"எட்டுத்தொகை – குறுந்தொகை"},{"id":504,"subject":"tamil","testNumber":6,"question":"நற்றிணை நூலைத் தொகுப்பித்த பாண்டிய மன்னன் யார்?","options":["ஆரியப்படை கடந்த நெடுஞ்செழியன்","பன்னாடு தந்த மாறன் வழுதி","கடலுள் மாய்ந்த இளம்பெருவழுதி","பாண்டியன் உக்கிரப்பெருவழுதி"],"correctAnswer":1,"explanation":"நற்றிணையைத் தொகுத்தவர் பெயர் தெரியவில்லை; ஆனால் அதனைத் தொகுப்பித்தவர் 'பன்னாடு தந்த பாண்டியன் மாறன் வழுதி' ஆவார். நற்றிணையின் அடி வரையறை 9 முதல் 12 அடிகள் ஆகும்.","difficulty":"medium","topic":"எட்டுத்தொகை – நற்றிணை"},{"id":505,"subject":"tamil","testNumber":6,"question":"குறுந்தொகைப் பாடல்களைத் தொகுத்த புலவர் யார்?","options":["கூடலூர் கிழார்","பூரிக்கோ","நல்லந்துவனார்","உருத்திரசன்மர்"],"correctAnswer":1,"explanation":"குறுந்தொகையைத் தொகுத்தவர் பூரிக்கோ ஆவார்; இதனைத் தொகுப்பித்தவர் பெயர் தெரியவில்லை. இந்நூலுக்குப் பாரதம் பாடிய பெருந்தேவனார் முருகப்பெருமானை வாழ்த்திக் கடவுள் வாழ்த்துப் பாடியுள்ளார்.","difficulty":"easy","topic":"எட்டுத்தொகை – குறுந்தொகை"},{"id":506,"subject":"tamil","testNumber":6,"question":"எட்டுத்தொகை நூல்களுள் மிகக் குறைந்த அடி வரையறை (3 முதல் 6 அடிகள்) கொண்ட நூல் எது?","options":["நற்றிணை","புறநானூறு","ஐங்குறுநூறு","குறுந்தொகை"],"correctAnswer":2,"explanation":"ஐங்குறுநூறு மூன்று அடி சிற்றெல்லையும் ஆறு அடி பேரெல்லையும் கொண்ட மிகச் சிறிய பாடல்களால் ஆனது. ஐந்து திணைகளுக்கும் திணைக்கு நூறு பாடல்கள் வீதம் ஐந்நூறு பாடல்களைக் கொண்டுள்ளது.","difficulty":"easy","topic":"எட்டுத்தொகை – ஐங்குறுநூறு"},{"id":507,"subject":"tamil","testNumber":6,"question":"ஐங்குறுநூற்றைத் தொகுத்தவர் மற்றும் தொகுப்பித்தவர் முறையே யாவர்?","options":["நல்லந்துவனார், இமயவரம்பன் நெடுஞ்சேரலாதன்","பூரிக்கோ, பாண்டியன் மாறன் வழுதி","உருத்திரசன்மர், பாண்டியன் உக்கிரப்பெருவழுதி","புலத்துறை முற்றிய கூடலூர் கிழார், யானைக்கட்சேய் மாந்தரஞ்சேரல் இரும்பொறை"],"correctAnswer":3,"explanation":"ஐங்குறுநூற்றைத் தொகுத்தவர் புலத்துறை முற்றிய கூடலூர் கிழார் ஆவார். இதனைத் தொகுப்பித்த சேர மன்னன் யானைக்கட்சேய் மாந்தரஞ்சேரல் இரும்பொறை ஆவார்.","difficulty":"medium","topic":"எட்டுத்தொகை – ஐங்குறுநூறு"},{"id":508,"subject":"tamil","testNumber":6,"question":"ஐங்குறுநூற்றில் மருதத் திணைப் பாடல்கள் நூறையும் பாடிய புலவர் யார்?","options":["பேயனார்","அம்மூவனார்","ஓரம்போகியார்","கபிலர்"],"correctAnswer":2,"explanation":"ஐங்குறுநூற்றில் மருதத் திணையை ஓரம்போகியாரும், நெய்தலை அம்மூவனாரும், குறிஞ்சியைக் கபிலரும், பாலையை ஓதலாந்தையாரும், முல்லையைப் பேயனாரும் தலா 100 பாடல்கள் வீதம் பாடியுள்ளனர்.","difficulty":"easy","topic":"எட்டுத்தொகை – ஐங்குறுநூறு"},{"id":509,"subject":"tamil","testNumber":6,"question":"ஐங்குறுநூற்றில் பாலைத் திணைப் பாடல்கள் நூறையும் பாடிய புலவர் யார்?","options":["பாலை பாடிய பெருங்கடுங்கோ","ஓதலாந்தையார்","பேயனார்","அம்மூவனார்"],"correctAnswer":1,"explanation":"ஐங்குறுநூற்றில் பாலைத் திணைப் பாடல்கள் (301 முதல் 400 வரை) நூறையும் பாடியவர் ஓதலாந்தையார் ஆவார். பாலை பாடிய பெருங்கடுங்கோ கலித்தொகையில் பாலைக்கலியைப் பாடியவர் ஆவார்.","difficulty":"medium","topic":"எட்டுத்தொகை – ஐங்குறுநூறு"},{"id":510,"subject":"tamil","testNumber":6,"question":"\"பிரசம் கலந்த வெண்சுவைத் தீம்பால்\" என்ற புகழ்பெற்ற நற்றிணைப் பாடலைப் பாடிய புலவர் யார்?","options":["போதனார்","நக்கீரர்","ஔவையார்","பெருந்தலைச் சாத்தனார்"],"correctAnswer":0,"explanation":"நற்றிணை 110-ஆம் பாடலான 'பிரசம் கலந்த வெண்சுவைத் தீம்பால்' என்ற பாடலைப் பாடியவர் போதனார் ஆவார். செல்வந்தர் வீட்டில் வளர்ந்த தலைவி, கணவன் வீட்டின் வறுமையிலும் பொழுதுக்கொரு முறை உணவுண்டு மகிழும் சிறப்பை இப்பாடல் கூறுகிறது.","difficulty":"hard","topic":"எட்டுத்தொகை – நற்றிணை"},{"id":511,"subject":"tamil","testNumber":6,"question":"\"யாயும் ஞாயும் யாரா கியரோ... செம்புலப் பெயல்நீர் போல\" என்ற அழகிய காதல் பாடல் இடம்பெற்றுள்ள நூல் எது?","options":["நற்றிணை","குறுந்தொகை","அகநானூறு","ஐங்குறுநூறு"],"correctAnswer":1,"explanation":"குறுந்தொகையின் 40-ஆம் பாடலான இப்பாடலை இயற்றியவர் இயற்பெயர் தெரியாததால், இப்பாடலின் சிறப்பான உவமையைக் கொண்டு 'செம்புலப்பெயல்நீரார்' என அழைக்கப்படுகிறார். செம்மண்ணில் பெய்த மழைநீர் போல அன்புடைய நெஞ்சங்கள் இரண்டறக் கலந்ததை இப்பாடல் உணர்த்துகிறது.","difficulty":"easy","topic":"எட்டுத்தொகை – குறுந்தொகை"},{"id":512,"subject":"tamil","testNumber":6,"question":"\"நிலத்தினும் பெரிதே வானினும் உயர்ந்தன்று நீரினும் ஆரள வின்றே\" என்ற குறுந்தொகைப் பாடலைப் பாடியவர் யார்?","options":["இறையனார்","கபிலர்","தேவகுலத்தார்","செம்புலப்பெயல்நீரார்"],"correctAnswer":2,"explanation":"குறுந்தொகையின் மூன்றாம் பாடலான இதனைப் பாடியவர் தேவகுலத்தார் ஆவார். குறிஞ்சி நிலத் தலைவனுடன் கொண்ட நட்பின் பெருமை நிலத்தைவிடப் பெரியதாகவும், வானைவிட உயர்ந்ததாகவும், கடலைவிட ஆழமானதாகவும் இருப்பதைத் தலைவி இதில் கூறுகிறாள்.","difficulty":"medium","topic":"எட்டுத்தொகை – குறுந்தொகை"},{"id":513,"subject":"tamil","testNumber":6,"question":"\"வினையே ஆடவர்க்கு உயிரே\" என்ற புகழ்பெற்ற சங்க இலக்கிய அடி இடம்பெற்றுள்ள நூல் எது?","options":["பதிற்றுப்பத்து","குறுந்தொகை","கலித்தொகை","புறநானூறு"],"correctAnswer":1,"explanation":"இவ்வரி குறுந்தொகையின் 135-ஆம் பாடலில் இடம்பெற்றுள்ளது. இதனைப் பாடியவர் பாலை பாடிய பெருங்கடுங்கோ ஆவார்; ஆடவர்களுக்குத் தொழில் முயற்சியே உயிர் போன்றது என்பதை இப்பாடல் உணர்த்துகிறது.","difficulty":"medium","topic":"எட்டுத்தொகை – குறுந்தொகை"},{"id":514,"subject":"tamil","testNumber":6,"question":"\"கொங்குதேர் வாழ்க்கை அஞ்சிறைத் தும்பி\" என்ற குறுந்தொகைப் பாடலைப் பாடியவர் யார்?","options":["நக்கீரர்","இறையனார்","பரணர்","ஓரம்போகியார்"],"correctAnswer":1,"explanation":"குறுந்தொகையின் இரண்டாம் பாடலான 'கொங்குதேர் வாழ்க்கை அஞ்சிறைத் தும்பி' என்ற பாடலைப் பாடியவர் இறையனார் ஆவார். தலைவியின் கூந்தலின் இயற்கை மணத்தைவிட நறுமணமிக்க மலர் உண்டோ எனத் தலைவன் வண்டைப் பார்த்து வினவுவதாக இப்பாடல் அமைந்துள்ளது.","difficulty":"easy","topic":"எட்டுத்தொகை – குறுந்தொகை"},{"id":515,"subject":"tamil","testNumber":6,"question":"சேர மன்னர்களின் வரலாற்றை அறிய உதவும் முதன்மை எட்டுத்தொகை நூல் எது?","options":["புறநானூறு","பரிபாடல்","அகநானூறு","பதிற்றுப்பத்து"],"correctAnswer":3,"explanation":"பதிற்றுப்பத்து பத்து சேர மன்னர்களைப் பற்றிப் பத்துப் புலவர்கள் தலா பத்துப் பாடல்கள் வீதம் பாடிய நூறு பாடல்களைக் கொண்ட புறப்பொருள் நூலாகும். சேர மன்னர்களின் வீரம், கொடை, ஆட்சிமுறை ஆகியவற்றைக் கூறுவதால் இது 'சேரர்களின் வரலாற்றுக் கருவூலம்' என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"எட்டுத்தொகை – பதிற்றுப்பத்து"},{"id":516,"subject":"tamil","testNumber":6,"question":"பதிற்றுப்பத்து நூலில் தற்போது நமக்குக் கிடைக்காமல் போன பகுதிகள் எவை?","options":["முதல் பத்தும் பத்தாம் பத்தும்","இரண்டாம் பத்தும் மூன்றாம் பத்தும்","ஐந்தாம் பத்தும் ஆறாம் பத்தும்","எட்டாம் பத்தும் ஒன்பதாம் பத்தும்"],"correctAnswer":0,"explanation":"பதிற்றுப்பத்து மொத்தம் 100 பாடல்களைக் கொண்டதாக இருந்தாலும், முதல் பத்தும் பத்தாம் பத்தும் கிடைக்கவில்லை. இரண்டாம் பத்து முதல் ஒன்பதாம் பத்து வரையிலான 80 பாடல்கள் மட்டுமே தற்போது நமக்குக் கிடைத்துள்ளன.","difficulty":"medium","topic":"எட்டுத்தொகை – பதிற்றுப்பத்து"},{"id":517,"subject":"tamil","testNumber":6,"question":"பதிற்றுப்பத்தில் அந்தாதித் தொடையில் அமைந்துள்ள பத்து எது?","options":["ஏழாம் பத்து","ஒன்பதாம் பத்து","நான்காம் பத்து","இரண்டாம் பத்து"],"correctAnswer":2,"explanation":"பதிற்றுப்பத்தின் நான்காம் பத்தைப் பாடியவர் காப்பியாற்றுக் காப்பியனார்; இதன் பாட்டுடைத் தலைவன் களங்காய்க்கண்ணி நார்முடிச்சேரல். இப்பத்தில் உள்ள பத்துப் பாடல்களும் அந்தாதித் தொடையில் அமைந்துள்ளன.","difficulty":"hard","topic":"எட்டுத்தொகை – பதிற்றுப்பத்து"},{"id":518,"subject":"tamil","testNumber":6,"question":"பதிற்றுப்பத்தில் கடல்பிறக்கோட்டிய செங்குட்டுவனைப் பற்றி ஐந்தாம் பத்தைப் பாடிய புலவர் யார்?","options":["பரணர்","கபிலர்","காக்கைப்பாடினியார் நச்செள்ளையார்","குமட்டூர்க் கண்ணனார்"],"correctAnswer":0,"explanation":"பதிற்றுப்பத்தின் ஐந்தாம் பத்தைக் கடல்பிறக்கோட்டிய செங்குட்டுவன் மீது பாடியவர் பரணர் ஆவார். சங்கப் புலவர்களுள் வரலாற்றுச் செய்திகளை மிகுதியாகத் தம் பாடல்களில் பதிவு செய்தவர் பரணர் என்பது குறிப்பிடத்தக்கது.","difficulty":"medium","topic":"எட்டுத்தொகை – பதிற்றுப்பத்து"},{"id":519,"subject":"tamil","testNumber":6,"question":"'ஓங்கு' என்ற அடைமொழி பெற்ற எட்டுத்தொகை இசைப்பாடல் நூல் எது?","options":["பரிபாடல்","கலித்தொகை","ஐங்குறுநூறு","நற்றிணை"],"correctAnswer":0,"explanation":"பரிபாடல் 'ஓங்கு பரிபாடல்' என்ற அடைமொழியுடன் போற்றப்படுகிறது. இசைப்பாடலாக அமைந்த இந்நூலில் பாடலைப் பாடிய புலவர் பெயருடன், அதற்கு இசையமைத்தவர் பெயரும் பண்ணின் பெயரும் குறிப்பிடப்பட்டுள்ளன.","difficulty":"easy","topic":"எட்டுத்தொகை – பரிபாடல்"},{"id":520,"subject":"tamil","testNumber":6,"question":"பரிபாடல் நூலுக்கு உரை எழுதிய புகழ்பெற்ற உரையாசிரியர் யார்?","options":["பேராசிரியர்","இளம்பூரணர்","நச்சினார்க்கினியர்","பரிமேலழகர்"],"correctAnswer":3,"explanation":"பரிபாடலுக்கு உரை எழுதியவர் பரிமேலழகர் ஆவார். பரிபாடலில் பழம்பாடல் கூறும் 70 பாடல்களுள் தற்போது திருமால் (6), செவ்வேள் (8), வையை (8) என 22 பாடல்கள் மட்டுமே முழுமையாகக் கிடைத்துள்ளன.","difficulty":"medium","topic":"எட்டுத்தொகை – பரிபாடல்"},{"id":521,"subject":"tamil","testNumber":6,"question":"\"விசும்பில் ஊழி ஊழ் ஊழ் செல்ல\" என்று அண்டத் தோற்றத்தை வர்ணிக்கும் பரிபாடல் பாடலைப் பாடியவர் யார்?","options":["கடுவன் இளவெயினனார்","நல்லந்துவனார்","கீரந்தையார்","கேசவனார்"],"correctAnswer":2,"explanation":"பரிபாடலின் இரண்டாம் பாடலான 'விசும்பில் ஊழி ஊழ் ஊழ் செல்ல' என்ற பாடலைப் பாடியவர் கீரந்தையார் ஆவார். வானம், காற்று, தீ, நீர், நிலம் ஆகிய ஐம்பூதங்கள் ஊழிக்காலங்களில் தோன்றிப் பூமி உருவான அறிவியல் கருத்தை இப்பாடல் உணர்த்துகிறது.","difficulty":"medium","topic":"எட்டுத்தொகை – பரிபாடல்"},{"id":522,"subject":"tamil","testNumber":6,"question":"'கற்றறிந்தார் ஏத்தும் கலி' என்று சிறப்பிக்கப்படும் கலித்தொகையைத் தொகுத்தவர் யார்?","options":["கபிலர்","நல்லந்துவனார்","பெருங்கடுங்கோ","மருதன் இளநாகனார்"],"correctAnswer":1,"explanation":"கலித்தொகையைத் தொகுத்தவர் நல்லந்துவனார் ஆவார்; இவரே இந்நூலின் கடவுள் வாழ்த்தையும் நெய்தற்கலியையும் பாடியுள்ளார். கடவுள் வாழ்த்துடன் சேர்த்து மொத்தம் 150 பாடல்களைக் கொண்டது கலித்தொகை.","difficulty":"easy","topic":"எட்டுத்தொகை – கலித்தொகை"},{"id":523,"subject":"tamil","testNumber":6,"question":"கலித்தொகையில் ஏறுதழுவுதல் பற்றிக் கூறும் முல்லைக்கலிப் பாடல்களைப் பாடியவர் யார்?","options":["மருதன் இளநாகனார்","பாலை பாடிய பெருங்கடுங்கோ","சோழன் நல்லுருத்திரன்","நல்லந்துவனார்"],"correctAnswer":2,"explanation":"கலித்தொகையில் முல்லைக்கலி (17 பாடல்கள்) பாடியவர் சோழன் நல்லுருத்திரன் ஆவார். ஆயர் குல வீரர்கள் காளையை அடக்கும் ஏறுதழுவுதல் வீர விளையாட்டை மிகத் தத்ரூபமாக முல்லைக்கலி வர்ணிக்கிறது.","difficulty":"medium","topic":"எட்டுத்தொகை – கலித்தொகை"},{"id":524,"subject":"tamil","testNumber":6,"question":"\"ஆற்றுதல் என்பது ஒன்று அலந்தவர்க்கு உதவுதல் / போற்றுதல் என்பது புணர்ந்தாரைப் பிரியாமை\" என்ற கலித்தொகைப் பாடலைப் பாடியவர் யார்?","options":["நல்லந்துவனார்","கபிலர்","மருதன் இளநாகனார்","சோழன் நல்லுருத்திரன்"],"correctAnswer":0,"explanation":"நெய்தற்கலியின் 133-ஆம் பாடலான இதனைப் பாடியவர் நல்லந்துவனார் ஆவார். பண்பு, அன்பு, அறிவு, செறிவு, நிறை, முறை, பொறை ஆகிய வாழ்வியல் அறங்களைத் தெளிவாக வரையறுக்கும் உயரிய பாடலாகும்.","difficulty":"medium","topic":"எட்டுத்தொகை – கலித்தொகை"},{"id":525,"subject":"tamil","testNumber":6,"question":"'நெடுந்தொகை' என்ற சிறப்புப் பெயர் பெற்ற எட்டுத்தொகை நூலும் அதன் அடி வரையறையும் எவை?","options":["நற்றிணை; 9 முதல் 12 அடிகள்","அகநானூறு; 13 முதல் 31 அடிகள்","புறநானூறு; 4 முதல் 40 அடிகள்","பரிபாடல்; 25 முதல் 400 அடிகள்"],"correctAnswer":1,"explanation":"அகநானூறு 13 அடி சிற்றெல்லையும் 31 அடி பேரெல்லையும் கொண்டு நீண்ட அகப்பாடல்களால் அமைந்ததால் 'நெடுந்தொகை' என்றும் அழைக்கப்படுகிறது. இதில் கடவுள் வாழ்த்து நீங்கலாக 400 பாடல்கள் உள்ளன.","difficulty":"easy","topic":"எட்டுத்தொகை – அகநானூறு"},{"id":526,"subject":"tamil","testNumber":6,"question":"அகநானூற்றைத் தொகுத்தவர் மற்றும் தொகுப்பித்தவர் முறையே யாவர்?","options":["பூரிக்கோ, பாண்டியன் மாறன் வழுதி","கூடலூர் கிழார், மாந்தரஞ்சேரல் இரும்பொறை","நல்லந்துவனார், பாண்டியன் நெடுஞ்செழியன்","உருத்திரசன்மர், பாண்டியன் உக்கிரப்பெருவழுதி"],"correctAnswer":3,"explanation":"அகநானூற்றைத் தொகுத்தவர் மதுரை உப்பூரிகுடி கிழார் மகனார் உருத்திரசன்மர் ஆவார். இதனைத் தொகுப்பித்தவர் பாண்டியன் உக்கிரப்பெருவழுதி ஆவார்.","difficulty":"medium","topic":"எட்டுத்தொகை – அகநானூறு"},{"id":527,"subject":"tamil","testNumber":6,"question":"அகநானூற்றின் மூன்று பிரிவுகளுள் 121 முதல் 300 வரையிலான 180 பாடல்களைக் கொண்ட பகுதி எது?","options":["களிற்றியானை நிரை","குறிஞ்சிக் கோவை","நித்திலக் கோவை","மணிமிடை பவளம்"],"correctAnswer":3,"explanation":"அகநானூறு மூன்று பெரும் பிரிவுகளாகப் பகுக்கப்பட்டுள்ளது: 1 முதல் 120 பாடல்கள் 'களிற்றியானை நிரை' (120 பாடல்கள்), 121 முதல் 300 பாடல்கள் 'மணிமிடை பவளம்' (180 பாடல்கள்), 301 முதல் 400 பாடல்கள் 'நித்திலக் கோவை' (100 பாடல்கள்).","difficulty":"medium","topic":"எட்டுத்தொகை – அகநானூறு"},{"id":528,"subject":"tamil","testNumber":6,"question":"அகநானூற்றில் 1, 3, 5, 7 என ஒற்றைப்படை எண்களில் வரிசைப்படுத்தப்பட்டுள்ள 200 பாடல்களும் எந்தத் திணைக்குரியவை?","options":["பாலைத் திணை","முல்லைத் திணை","மருதத் திணை","குறிஞ்சித் திணை"],"correctAnswer":0,"explanation":"அகநானூறு ஒழுங்குபடுத்தப்பட்ட எண் வரிசை அமைப்பைக் கொண்டது. இதில் 1, 3, 5, 7, 9 என முடியும் ஒற்றைப்படை எண்கள் அனைத்தும் (200 பாடல்கள்) பாலைத் திணைக்கும், 2, 8 குறிஞ்சிக்கும், 4 முல்லைக்கும், 6 மருதத்திற்கும், 10 நெய்தலுக்கும் உரியன.","difficulty":"medium","topic":"எட்டுத்தொகை – அகநானூறு"},{"id":529,"subject":"tamil","testNumber":6,"question":"\"யவனர் தந்த வினைமாண் நன்கலம் பொன்னொடு வந்து கறியொடு பெயரும்\" என்ற அகநானூற்றுப் பாடல் (149) குறிப்பிடும் பண்டைய துறைமுகம் எது?","options":["முசிறி","புகார்","கொற்கை","தொண்டி"],"correctAnswer":0,"explanation":"எருக்காட்டூர்த் தாயங்கண்ணனார் பாடிய அகநானூறு 149-ஆம் பாடலில், சேர நாட்டின் பேரியாற்றுக் கரையில் அமைந்த முசிறித் துறைமுகத்திற்கு யவனர்கள் பொன்னுடன் கப்பல்களில் வந்து மிளகை (கறி) ஏற்றிச் சென்ற வணிகச் சிறப்பு கூறப்பட்டுள்ளது.","difficulty":"hard","topic":"எட்டுத்தொகை – அகநானூறு"},{"id":530,"subject":"tamil","testNumber":6,"question":"பண்டைய தமிழர்களின் குடவோலைத் தேர்தல் முறை பற்றிக் குறிப்பிடும் சங்க இலக்கிய எட்டுத்தொகை நூல் எது?","options":["புறநானூறு","அகநானூறு","நற்றிணை","பதிற்றுப்பத்து"],"correctAnswer":1,"explanation":"அகநானூற்றின் 77-ஆம் பாடலில் (மருதன் இளநாகனார்) 'கயிறுபிணிக் குழிசி ஓலை கொண்மார் பொறிகண்டு அழிக்கும் ஆவண மாக்கள்' எனக் குடவோலைத் தேர்தல் முறை குறித்த பழமையான இலக்கியச் சான்று இடம்பெற்றுள்ளது.","difficulty":"hard","topic":"எட்டுத்தொகை – அகநானூறு"},{"id":531,"subject":"tamil","testNumber":6,"question":"கீழ்க்காணும் எட்டுத்தொகை நூல்களுள் பாரதம் பாடிய பெருந்தேவனார் கடவுள் வாழ்த்துப் பாடாத நூல் எது?","options":["குறுந்தொகை","நற்றிணை","கலித்தொகை","புறநானூறு"],"correctAnswer":2,"explanation":"எட்டுத்தொகை நூல்களுள் நற்றிணை, குறுந்தொகை, ஐங்குறுநூறு, அகநானூறு, புறநானூறு ஆகிய ஐந்து நூல்களுக்கும் பாரதம் பாடிய பெருந்தேவனார் கடவுள் வாழ்த்துப் பாடியுள்ளார். கலித்தொகைக்கு மட்டும் அதனைத் தொகுத்த நல்லந்துவனாரே கடவுள் வாழ்த்துப் பாடியுள்ளார்.","difficulty":"hard","topic":"எட்டுத்தொகை – கடவுள் வாழ்த்து"},{"id":532,"subject":"tamil","testNumber":6,"question":"\"யாதும் ஊரே யாவரும் கேளிர் / தீதும் நன்றும் பிறர்தர வாரா\" என்ற உலகப் பொதுமைக் கருத்தைப் பாடிய புலவர் யார்?","options":["நரிவெரூஉத்தலையார்","கணியன் பூங்குன்றனார்","பிசிராந்தையார்","குடபுலவியனார்"],"correctAnswer":1,"explanation":"புறநானூற்றின் 192-ஆம் பாடலான இப்பொன்மொழியைப் பாடியவர் கணியன் பூங்குன்றனார் ஆவார். எல்லா ஊரும் நம் ஊரே, எல்லாரும் நம் உறவினரே, நன்மையும் தீமையும் பிறரால் வருவன அல்ல என்ற உயரிய மெய்யியல் சிந்தனையை இப்பாடல் வெளிப்படுத்துகிறது.","difficulty":"easy","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":533,"subject":"tamil","testNumber":6,"question":"\"உண்டி கொடுத்தோர் உயிர் கொடுத்தோரே\" என்ற புகழ்பெற்ற புறநானூற்று அடியைப் பாடிய புலவர் யார்?","options":["குடபுலவியனார்","கபிலர்","நக்கீரர்","மோசிகீரனார்"],"correctAnswer":0,"explanation":"புறநானூற்றின் 18-ஆம் பாடலில் பாண்டியன் நெடுஞ்செழியனுக்கு நீர்நிலைகளைப் பெருக்கி உணவை வளர்க்க அறிவுறுத்தும் குடபுலவியனார், 'உண்டி கொடுத்தோர் உயிர் கொடுத்தோரே' என்று உணவு அளிப்போரின் பெருமையைப் போற்றியுள்ளார்.","difficulty":"medium","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":534,"subject":"tamil","testNumber":6,"question":"\"செல்வத்துப் பயனே ஈதல் துய்ப்பேம் எனினே தப்புந பலவே\" என்ற புறநானூற்று அடிகளைப் பாடியவர் யார்?","options":["ஔவையார்","நக்கீரர்","பரணர்","கணியன் பூங்குன்றனார்"],"correctAnswer":1,"explanation":"மதுரைக் கணக்காயனார் மகனார் நக்கீரனார் பாடிய புறநானூறு 189-ஆம் பாடலில் இவ்வடிகள் இடம்பெற்றுள்ளன. செல்வத்தைத் தாமே நுகர்வோம் எனக் கருதினால் பல நன்மைகள் தவறிவிடும்; பிறருக்குக் கொடுத்து உதவுவதே செல்வத்தின் உண்மையான பயன் என இப்பாடல் வலியுறுத்துகிறது.","difficulty":"medium","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":535,"subject":"tamil","testNumber":6,"question":"\"உண்டாலம்ம இவ்வுலகம் இந்திரர் அமிழ்தம் இயைவதாயினும்\" என்ற புறநானூற்றுப் பாடலைப் பாடியவர் யார்?","options":["அதியமான் நெடுமான் அஞ்சி","ஆரியப்படை கடந்த நெடுஞ்செழியன்","கோப்பெருஞ்சோழன்","கடலுள் மாய்ந்த இளம்பெருவழுதி"],"correctAnswer":3,"explanation":"புறநானூற்றின் 182-ஆம் பாடலைப் பாடியவர் கடலுள் மாய்ந்த இளம்பெருவழுதி என்ற பாண்டிய மன்னர் ஆவார். அமிழ்தமே கிடைத்தாலும் தனித்து உண்ணாதவரும், தனக்கென வாழாது பிறர்க்கென வாழ்பவருமான சான்றோரால் இவ்வுலகம் நிலைபெற்றுள்ளது என்பதை இப்பாடல் கூறுகிறது.","difficulty":"medium","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":536,"subject":"tamil","testNumber":6,"question":"\"எவ்வழி நல்லவர் ஆடவர் அவ்வழி நல்லை வாழிய நிலனே\" என்று பாடிய சங்கப் புலவர் யார்?","options":["வெள்ளிவீதியார்","காக்கைப்பாடினியார்","பொன்முடியார்","ஔவையார்"],"correctAnswer":3,"explanation":"புறநானூற்றின் 187-ஆம் பாடலைப் பாடியவர் ஔவையார் ஆவார். நாடாக இருந்தாலும் காடாக இருந்தாலும் பள்ளமாக இருந்தாலும் மேடாக இருந்தாலும், அங்கே வாழும் மக்கள் நல்லவர்களாக இருந்தால் அந்நிலமும் நல்லதாகவே விளங்கும் என்பது இப்பாடலின் கருத்தாகும்.","difficulty":"easy","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":537,"subject":"tamil","testNumber":6,"question":"\"உற்றுழி உதவியும் உறுபொருள் கொடுத்தும் பிற்றைநிலை முனியாது கற்றல் நன்றே\" என்று கல்வியின் மேன்மையைப் பாடிய மன்னர் யார்?","options":["கடலுள் மாய்ந்த இளம்பெருவழுதி","ஆரியப்படை கடந்த நெடுஞ்செழியன்","இளஞ்சேரல் இரும்பொறை","கரிகால் பெருவளத்தான்"],"correctAnswer":1,"explanation":"புறநானூற்றின் 183-ஆம் பாடலைப் பாடியவர் ஆரியப்படை கடந்த பாண்டியன் நெடுஞ்செழியன் ஆவார். ஆசிரியருக்கு உற்ற காலத்தில் உதவி செய்தும், வேண்டிய பொருளைக் கொடுத்தும், பணிந்து நின்று கல்வி கற்பது மிகவும் சிறந்தது என இப்பாடல் அறிவுறுத்துகிறது.","difficulty":"medium","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":538,"subject":"tamil","testNumber":6,"question":"\"நெல்லும் உயிரன்றே நீரும் உயிரன்றே மன்னன் உயிர்த்தே மலர்தலை உலகம்\" என்று பாடிய புறநானூற்றுப் புலவர் யார்?","options":["மோசிகீரனார்","கபிலர்","குடபுலவியனார்","பிசிராந்தையார்"],"correctAnswer":0,"explanation":"புறநானூற்றின் 186-ஆம் பாடலைப் பாடியவர் மோசிகீரனார் ஆவார். பரந்த இவ்வுலகத்திற்கு நெல்லும் நீரும் மட்டும் உயிராகாது; அறநெறியோடு ஆட்சி புரியும் மன்னனே உலகத்தின் உயிர் என்பதை ஆட்சியாளரின் பொறுப்பாக இப்பாடல் உணர்த்துகிறது.","difficulty":"hard","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":539,"subject":"tamil","testNumber":6,"question":"சங்க இலக்கியத்தில் குறிஞ்சித் திணைப் பாடல்களை மிகுதியாகப் பாடியதால் 'குறிஞ்சிக் கபிலர்' எனப் போற்றப்பட்ட கபிலர் யாருடைய உயிர்த்தோழராக விளங்கினார்?","options":["வேள் பாரி","பேகன்","ஆய் அண்டிரன்","அதியமான்"],"correctAnswer":0,"explanation":"கபிலர் பறம்பு மலையை ஆண்ட கடையேழு வள்ளல்களில் ஒருவரான வேள் பாரியின் உயிர்த்தோழரும் அவைக்களப் புலவரும் ஆவார். பாரியின் மறைவிற்குப் பிறகு அவரது மகளிரைப் பாதுகாத்துத் திருமணம் செய்து வைத்து, வடக்கிருந்து உயிர் நீத்த நட்பின் சிகரமாக விளங்கினார்.","difficulty":"easy","topic":"எட்டுத்தொகை – சங்கப் புலவர்கள்"},{"id":540,"subject":"tamil","testNumber":6,"question":"'தமிழர் வரலாற்றுக் களஞ்சியம்' எனப் போற்றப்படும் புறநானூற்றை முதன்முதலில் அச்சில் பதிப்பித்து வெளியிட்டவர் யார்?","options":["ஆறுமுக நாவலர்","சி.வை. தாமோதரனார்","உ.வே. சாமிநாதையர்","ஜி.யு. போப்"],"correctAnswer":2,"explanation":"'தமிழ்த் தாத்தா' எனப் போற்றப்படும் உ.வே. சாமிநாதையர் 1894-ஆம் ஆண்டு புறநானூற்றை முதன்முதலில் பதிப்பித்துத் தமிழுலகிற்கு வழங்கினார். இதன் சில பாடல்களை ஜி.யு. போப் ஆங்கிலத்தில் மொழிபெயர்த்துள்ளார்.","difficulty":"easy","topic":"எட்டுத்தொகை – புறநானூறு"},{"id":541,"subject":"tamil","testNumber":6,"question":"பத்துப்பாட்டு நூல்கள் பத்தும் முழுமைக்கும் உரை எழுதிய உரையாசிரியர் யார்?","options":["அடியார்க்கு நல்லார்","நச்சினார்க்கினியர்","பரிமேலழகர்","மணக்குடவர்"],"correctAnswer":1,"explanation":"பத்துப்பாட்டு நூல்கள் பத்தும் முழுமைக்கும் சிறப்புமிக்க உரை எழுதியவர் 'உச்சிமேல் புலவர்கொள் நச்சினார்க்கினியர்' ஆவார். பத்துப்பாட்டை 1889-ஆம் ஆண்டு உ.வே. சாமிநாதையர் முதன்முதலில் பதிப்பித்து வெளியிட்டார்.","difficulty":"easy","topic":"பத்துப்பாட்டு – பொது அறிமுகம்"},{"id":542,"subject":"tamil","testNumber":6,"question":"பத்துப்பாட்டு நூல்களுள் ஆற்றுப்படை இலக்கியங்களாக அமைந்துள்ள நூல்களின் எண்ணிக்கை எத்தனை?","options":["நான்கு","ஆறு","ஐந்து","மூன்று"],"correctAnswer":2,"explanation":"பத்துப்பாட்டில் திருமுருகாற்றுப்படை, பொருநராற்றுப்படை, சிறுபாணாற்றுப்படை, பெரும்பாணாற்றுப்படை, மலைபடுகடாம் (கூத்தராற்றுப்படை) ஆகிய ஐந்து நூல்களும் ஆற்றுப்படை நூல்களாகும். இவை அனைத்தும் புறப்பொருள் நூல்கள்.","difficulty":"easy","topic":"பத்துப்பாட்டு – பொது அறிமுகம்"},{"id":543,"subject":"tamil","testNumber":6,"question":"'புலவராற்றுப்படை' என்ற சிறப்புப் பெயரால் அழைக்கப்படும் பத்துப்பாட்டு நூல் எது?","options":["திருமுருகாற்றுப்படை","பொருநராற்றுப்படை","சிறுபாணாற்றுப்படை","மலைபடுகடாம்"],"correctAnswer":0,"explanation":"திருமுருகாற்றுப்படை 'புலவராற்றுப்படை' என்றும் அழைக்கப்படுகிறது. முருகப்பெருமானின் அருளைப் பெற்ற புலவர் ஒருவர், அருளைப் பெற விரும்பும் மற்றொரு புலவரை முருகனிடம் வழிப்படுத்துவதாக இந்நூல் அமைந்துள்ளது.","difficulty":"easy","topic":"பத்துப்பாட்டு – திருமுருகாற்றுப்படை"},{"id":544,"subject":"tamil","testNumber":6,"question":"பத்துப்பாட்டு நூல்களுள் சைவத் திருமுறைகளின் பதினோராம் திருமுறையில் இடம்பெற்றுள்ள நூல் எது?","options":["நெடுநல்வாடை","மதுரைக்காஞ்சி","திருமுருகாற்றுப்படை","குறிஞ்சிப்பாட்டு"],"correctAnswer":2,"explanation":"நக்கீரர் இயற்றிய திருமுருகாற்றுப்படை சங்க இலக்கியமான பத்துப்பாட்டிலும், பக்தி இலக்கியமான சைவத் திருமுறைகளின் பதினோராம் திருமுறையிலும் இடம்பெறும் பெருமை பெற்றது. இந்நூல் முருகனின் அறுபடை வீடுகளைப் போற்றிப் பாடுகிறது.","difficulty":"medium","topic":"பத்துப்பாட்டு – திருமுருகாற்றுப்படை"},{"id":545,"subject":"tamil","testNumber":6,"question":"திருமுருகாற்றுப்படையின் ஆசிரியர் மற்றும் மொத்த அடிகளின் எண்ணிக்கை முறையே எவை?","options":["நக்கீரர், 317 அடிகள்","முடத்தாமக்கண்ணியார், 248 அடிகள்","மாங்குடி மருதனார், 782 அடிகள்","கபிலர், 261 அடிகள்"],"correctAnswer":0,"explanation":"திருமுருகாற்றுப்படையை இயற்றியவர் மதுரைக் கணக்காயனார் மகனார் நக்கீரர் ஆவார். இந்நூல் 317 ஆசிரியப்பா அடிகளைக் கொண்டுள்ளது; பத்துப்பாட்டில் கடவுள் வாழ்த்துப் போல முதலாவதாக வைக்கப்பட்டுள்ளது.","difficulty":"easy","topic":"பத்துப்பாட்டு – திருமுருகாற்றுப்படை"},{"id":546,"subject":"tamil","testNumber":6,"question":"பொருநராற்றுப்படை என்ற பத்துப்பாட்டு நூலை இயற்றிய புலவர் யார்?","options":["நப்பூதனார்","பெருங்கௌசிகனார்","நல்லூர் நத்தத்தனார்","முடத்தாமக்கண்ணியார்"],"correctAnswer":3,"explanation":"பொருநராற்றுப்படையை இயற்றியவர் முடத்தாமக்கண்ணியார் ஆவார். 248 அடிகளைக் கொண்ட இந்நூலில் பாலை யாழின் வருணனை, சோழ நாட்டின் காவிரி வளம், விருந்தோம்பல் ஆகியவை சிறப்பாகப் பாடப்பட்டுள்ளன.","difficulty":"easy","topic":"பத்துப்பாட்டு – பொருநராற்றுப்படை"},{"id":547,"subject":"tamil","testNumber":6,"question":"பொருநராற்றுப்படையின் பாட்டுடைத் தலைவனாகப் போற்றப்படும் சோழ மன்னன் யார்?","options":["கரிகால் பெருவளத்தான்","சோழன் நலங்கிள்ளி","கோப்பெருஞ்சோழன்","சோழன் செங்கணான்"],"correctAnswer":0,"explanation":"பொருநராற்றுப்படையின் பாட்டுடைத் தலைவன் கரிகால் பெருவளத்தான் ஆவார். கரிகாலன் வெண்ணிப் போரில் சேர, பாண்டிய மன்னர்களை வென்ற சிறப்பும், விருந்தினரை ஏழடி பின்சென்று வழியனுப்பும் பண்பும் இந்நூலில் கூறப்பட்டுள்ளன.","difficulty":"medium","topic":"பத்துப்பாட்டு – பொருநராற்றுப்படை"},{"id":548,"subject":"tamil","testNumber":6,"question":"கடையேழு வள்ளல்கள் எழுவரின் கொடைச் சிறப்பையும் வரிசையாகப் பட்டியலிட்டுப் புகழும் பத்துப்பாட்டு நூல் எது?","options":["பொருநராற்றுப்படை","சிறுபாணாற்றுப்படை","பெரும்பாணாற்றுப்படை","மதுரைக்காஞ்சி"],"correctAnswer":1,"explanation":"நல்லூர் நத்தத்தனார் இயற்றிய சிறுபாணாற்றுப்படையில் பேகன், பாரி, காரி, ஆய், அதிகன், நள்ளி, ஓரி ஆகிய கடையேழு வள்ளல்களின் கொடைச் சிறப்புகள் ஒருசேரப் பாடப்பட்டு, அவர்களையெல்லாம் விஞ்சிய வள்ளலாக நல்லியக்கோடன் போற்றப்படுகிறான்.","difficulty":"easy","topic":"பத்துப்பாட்டு – சிறுபாணாற்றுப்படை"},{"id":549,"subject":"tamil","testNumber":6,"question":"சிறுபாணாற்றுப்படையின் ஆசிரியர் மற்றும் பாட்டுடைத் தலைவர் முறையே யாவர்?","options":["முடத்தாமக்கண்ணியார், கரிகால் பெருவளத்தான்","கடியலூர் உருத்திரங்கண்ணனார், தொண்டைமான் இளந்திரையன்","நல்லூர் நத்தத்தனார், ஓய்மாநாட்டு நல்லியக்கோடன்","பெருங்கௌசிகனார், நன்னன் சேய் நன்னன்"],"correctAnswer":2,"explanation":"சிறுபாணாற்றுப்படையை இயற்றியவர் இடைக்கழிநாட்டு நல்லூர் நத்தத்தனார்; இதன் பாட்டுடைத் தலைவன் ஓய்மாநாட்டு நல்லியக்கோடன் ஆவார். இந்நூல் 269 அடிகளைக் கொண்டுள்ளது.","difficulty":"medium","topic":"பத்துப்பாட்டு – சிறுபாணாற்றுப்படை"},{"id":550,"subject":"tamil","testNumber":6,"question":"'பாணாறு' என்ற சிறப்புப் பெயரால் அழைக்கப்படும் பெரும்பாணாற்றுப்படையை இயற்றியவர் யார்?","options":["நல்லூர் நத்தத்தனார்","மாங்குடி மருதனார்","கடியலூர் உருத்திரங்கண்ணனார்","நக்கீரர்"],"correctAnswer":2,"explanation":"பெரும்பாணாற்றுப்படையை இயற்றியவர் கடியலூர் உருத்திரங்கண்ணனார் ஆவார். பெரிய யாழை வாசிக்கும் பெரும்பாணனைக் காஞ்சி நகர் மன்னன் தொண்டைமான் இளந்திரையனிடம் ஆற்றுப்படுத்துவதாக அமைந்ததால் இதற்குப் பெரும்பாணாற்றுப்படை (பாணாறு) எனப் பெயர் வந்தது.","difficulty":"easy","topic":"பத்துப்பாட்டு – பெரும்பாணாற்றுப்படை"},{"id":551,"subject":"tamil","testNumber":6,"question":"\"வானம் ஊன்றிய மதலை போல / ஏணி சாத்திய ஏற்றருஞ் சென்னி\" என்று கலங்கரை விளக்கத்தை வர்ணிக்கும் பத்துப்பாட்டு நூல் எது?","options":["பெரும்பாணாற்றுப்படை","மதுரைக்காஞ்சி","பட்டினப்பாலை","சிறுபாணாற்றுப்படை"],"correctAnswer":0,"explanation":"கடியலூர் உருத்திரங்கண்ணனார் இயற்றிய பெரும்பாணாற்றுப்படையில், கடலில் செல்லும் மரக்கலங்களுக்கு வழிகாட்டும் கலங்கரை விளக்கம் வானத்தைத் தாங்கும் தூண் போல் உயர்ந்து நிற்பதாக அழகிய உவமையுடன் வர்ணிக்கப்பட்டுள்ளது.","difficulty":"medium","topic":"பத்துப்பாட்டு – பெரும்பாணாற்றுப்படை"},{"id":552,"subject":"tamil","testNumber":6,"question":"பெரும்பாணாற்றுப்படையின் பாட்டுடைத் தலைவனும் அதன் மொத்த அடிகளும் முறையே எவை?","options":["கரிகால் பெருவளத்தான், 301 அடிகள்","தொண்டைமான் இளந்திரையன், 500 அடிகள்","ஓய்மாநாட்டு நல்லியக்கோடன், 269 அடிகள்","நன்னன் சேய் நன்னன், 583 அடிகள்"],"correctAnswer":1,"explanation":"பெரும்பாணாற்றுப்படையின் பாட்டுடைத் தலைவன் காஞ்சியை ஆண்ட தொண்டைமான் இளந்திரையன் ஆவார். 500 அடிகளைக் கொண்ட இந்நூல் ஐவகை நிலங்களின் இயற்கை வளத்தையும் மக்களின் வாழ்வியலையும் விரிவாகக் கூறுகிறது.","difficulty":"medium","topic":"பத்துப்பாட்டு – பெரும்பாணாற்றுப்படை"},{"id":553,"subject":"tamil","testNumber":6,"question":"பத்துப்பாட்டு நூல்களுள் மிகக் குறைந்த அடிகளை (103 அடிகள்) கொண்ட நூல் எது?","options":["குறிஞ்சிப்பாட்டு","பொருநராற்றுப்படை","நெடுநல்வாடை","முல்லைப்பாட்டு"],"correctAnswer":3,"explanation":"பத்துப்பாட்டு நூல்களுள் மிகச் சிறிய நூலான முல்லைப்பாட்டு 103 ஆசிரியப்பா அடிகளை மட்டுமே கொண்டுள்ளது. பத்துப்பாட்டில் மிகப் பெரிய நூல் 782 அடிகளைக் கொண்ட மதுரைக்காஞ்சியாகும்.","difficulty":"easy","topic":"பத்துப்பாட்டு – முல்லைப்பாட்டு"},{"id":554,"subject":"tamil","testNumber":6,"question":"முல்லைப்பாட்டை இயற்றிய சங்கப் புலவர் யார்?","options":["நப்பூதனார்","கபிலர்","மாங்குடி மருதனார்","நக்கீரர்"],"correctAnswer":0,"explanation":"முல்லைப்பாட்டை இயற்றியவர் காவிரிப்பூம்பட்டினத்துப் பொன்வணிகனார் மகனார் நப்பூதனார் ஆவார். இது அகப்பொருள் நூலாகையால் இதில் பாட்டுடைத் தலைவனின் இயற்பெயர் சுட்டப்படவில்லை.","difficulty":"easy","topic":"பத்துப்பாட்டு – முல்லைப்பாட்டு"},{"id":555,"subject":"tamil","testNumber":6,"question":"'நெஞ்சாற்றுப்படை' என்று தமிழ் அறிஞர்களால் சிறப்பிக்கப்படும் பத்துப்பாட்டு நூல் எது?","options":["பட்டினப்பாலை","முல்லைப்பாட்டு","நெடுநல்வாடை","குறிஞ்சிப்பாட்டு"],"correctAnswer":1,"explanation":"தலைவனைப் பிரிந்த தலைவி தன் நெஞ்சத்தை ஆற்றுப்படுத்திக் கொள்வதாக அமைந்துள்ளதால் முல்லைப்பாட்டிற்கு 'நெஞ்சாற்றுப்படை' என்ற சிறப்புப் பெயரும் உண்டு. இது கார்கால வருணனையை மிக நுட்பமாகக் கூறுகிறது.","difficulty":"hard","topic":"பத்துப்பாட்டு – முல்லைப்பாட்டு"},{"id":556,"subject":"tamil","testNumber":6,"question":"முல்லைப்பாட்டில் தலைவியின் பிரிவுத் துயர் தீர முதுபெண்டிர் மேற்கொள்ளும் 'விரிச்சி கேட்டல்' என்பதன் பொருள் என்ன?","options":["மன்னனை வாழ்த்துதல்","தூது அனுப்புதல்","மழை வேண்டிப் பாடுதல்","நற்சொல் கேட்டல்"],"correctAnswer":3,"explanation":"ஏதேனும் ஒரு செயல் நன்றாக முடியுமோ முடியாதோ என ஐயம் கொள்ளும் பெண்கள், ஊரின் ஒருபுறம் சென்று தெய்வத்தைத் தொழுது அயலார் பேசும் நற்சொல்லைக் கேட்பதே 'விரிச்சி கேட்டல்' எனப்படும். முல்லைப்பாட்டில் இடைமகள் கன்றிடம் கூறிய சொல் நற்சொல்லாகக் கொள்ளப்படுகிறது.","difficulty":"medium","topic":"பத்துப்பாட்டு – முல்லைப்பாட்டு"},{"id":557,"subject":"tamil","testNumber":6,"question":"பத்துப்பாட்டு நூல்களுள் மிக அதிக அடிகளை (782 அடிகள்) கொண்ட நூல் எது?","options":["மதுரைக்காஞ்சி","மலைபடுகடாம்","பெரும்பாணாற்றுப்படை","திருமுருகாற்றுப்படை"],"correctAnswer":0,"explanation":"மதுரைக்காஞ்சி 782 அடிகளைக் கொண்டு பத்துப்பாட்டு நூல்களுள் மிகப் பெரிய நூலாகத் திகழ்கிறது. இதற்கு அடுத்தபடியாக மலைபடுகடாம் 583 அடிகளையும், பெரும்பாணாற்றுப்படை 500 அடிகளையும் கொண்டுள்ளன.","difficulty":"easy","topic":"பத்துப்பாட்டு – மதுரைக்காஞ்சி"},{"id":558,"subject":"tamil","testNumber":6,"question":"மதுரைக்காஞ்சியின் ஆசிரியர் மற்றும் பாட்டுடைத் தலைவர் முறையே யாவர்?","options":["நக்கீரர், பாண்டியன் உக்கிரப்பெருவழுதி","மாங்குடி மருதனார், தலையாலங்கானத்துச் செருவென்ற பாண்டியன் நெடுஞ்செழியன்","கபிலர், ஆரிய அரசன் பிரகத்தன்","உருத்திரங்கண்ணனார், கரிகால் பெருவளத்தான்"],"correctAnswer":1,"explanation":"மதுரைக்காஞ்சியை இயற்றியவர் மாங்குடி மருதனார்; இதன் பாட்டுடைத் தலைவன் தலையாலங்கானத்துச் செருவென்ற பாண்டியன் நெடுஞ்செழியன் ஆவார். நிலையாமையை உணர்த்தி வீடுபேற்று நெறியைக் காஞ்சித் திணையில் கூறுவதால் இதற்கு 'மதுரைக்காஞ்சி' எனப் பெயர் ஏற்பட்டது.","difficulty":"medium","topic":"பத்துப்பாட்டு – மதுரைக்காஞ்சி"},{"id":559,"subject":"tamil","testNumber":6,"question":"மதுரையில் செயல்பட்ட 'நாளங்காடி' (பகல் கடை) மற்றும் 'அல்லங்காடி' (இரவுக் கடை) ஆகியவற்றை விரிவாக வர்ணிக்கும் பத்துப்பாட்டு நூல் எது?","options":["பட்டினப்பாலை","மதுரைக்காஞ்சி","திருமுருகாற்றுப்படை","நெடுநல்வாடை"],"correctAnswer":1,"explanation":"'கூடற்றமிழ்' எனப் போற்றப்படும் மதுரைக்காஞ்சி, மாமதுரை நகரின் அகழி, கோட்டை, வீதிகள் மற்றும் நாளங்காடி, அல்லங்காடி ஆகிய பகல்-இரவு வணிக அங்காடிகளின் வளத்தைத் தத்ரூபமாகப் படம் பிடித்துக் காட்டுகிறது.","difficulty":"medium","topic":"பத்துப்பாட்டு – மதுரைக்காஞ்சி"},{"id":560,"subject":"tamil","testNumber":6,"question":"நெடுநல்வாடையின் ஆசிரியர் மற்றும் அதன் மொத்த அடிகளின் எண்ணிக்கை முறையே எவை?","options":["கபிலர், 261 அடிகள்","மாங்குடி மருதனார், 317 அடிகள்","நப்பூதனார், 103 அடிகள்","நக்கீரர், 188 அடிகள்"],"correctAnswer":3,"explanation":"நெடுநல்வாடையை இயற்றியவர் மதுரைக் கணக்காயனார் மகனார் நக்கீரர் ஆவார். 188 அடிகளைக் கொண்ட இந்நூல், பாண்டியன் நெடுஞ்செழியனின் பாசறைக் காட்சியையும் அரண்மனைக் கட்டடக் கலையையும் சிறப்பாகக் கூறுகிறது.","difficulty":"medium","topic":"பத்துப்பாட்டு – நெடுநல்வாடை"},{"id":561,"subject":"tamil","testNumber":6,"question":"பத்துப்பாட்டில் அகப்பொருளும் புறப்பொருளும் கலந்த 'அகப்புற நூலாக' அறிஞர்களால் போற்றப்படும் நூல் எது?","options":["பட்டினப்பாலை","குறிஞ்சிப்பாட்டு","நெடுநல்வாடை","முல்லைப்பாட்டு"],"correctAnswer":2,"explanation":"நெடுநல்வாடையில் தலைவனைப் பிரிந்த தலைவியின் வாடைக் காலப் பிரிவுத் துயரம் அகப்பொருளாகவும், பாண்டியனின் அடையாளப் பூவான வேப்பமாலை சுட்டப்படுவது புறப்பொருளாகவும் அமைந்துள்ளது. இதனால் இந்நூல் 'அகப்புற நூல்' எனச் சிறப்பிக்கப்படுகிறது.","difficulty":"hard","topic":"பத்துப்பாட்டு – நெடுநல்வாடை"},{"id":562,"subject":"tamil","testNumber":6,"question":"ஆரிய அரசன் பிரகத்தனுக்குத் தமிழின் அருமை பெருமைகளை அறிவுறுத்துவதற்காகக் கபிலர் பாடிய பத்துப்பாட்டு நூல் எது?","options":["மதுரைக்காஞ்சி","குறிஞ்சிப்பாட்டு","முல்லைப்பாட்டு","பட்டினப்பாலை"],"correctAnswer":1,"explanation":"ஆரிய அரசன் பிரகத்தனுக்குத் தமிழ் அகப்பொருளின் மாண்பையும் களவு-கற்பு ஒழுக்கத்தையும் அறிவுறுத்துவதற்காகக் கபிலர் 'குறிஞ்சிப்பாட்டு' என்ற 261 அடிகள் கொண்ட நூலைப் பாடினார். இதற்குப் 'பெருங்குறிஞ்சி' என்ற சிறப்புப் பெயரும் உண்டு.","difficulty":"easy","topic":"பத்துப்பாட்டு – குறிஞ்சிப்பாட்டு"},{"id":563,"subject":"tamil","testNumber":6,"question":"99 வகையான மலர்களின் பெயர்களை வரிசையாகப் பட்டியலிட்டுப் பாடும் சங்க இலக்கிய நூல் எது?","options":["பட்டினப்பாலை","மலைபடுகடாம்","முல்லைப்பாட்டு","குறிஞ்சிப்பாட்டு"],"correctAnswer":3,"explanation":"கபிலர் இயற்றிய குறிஞ்சிப்பாட்டில் 'ஒண்செங் காந்தள் ஆம்பல் அனிச்சம்' எனத் தொடங்கி 99 வகையான தமிழ் மலர்களின் பெயர்கள் ஒரே மூச்சில் வரிசையாகப் பாடப்பட்டுள்ளன. இது தமிழர்களின் தாவரவியல் அறிவிற்குச் சிறந்த சான்றாகும்.","difficulty":"easy","topic":"பத்துப்பாட்டு – குறிஞ்சிப்பாட்டு"},{"id":564,"subject":"tamil","testNumber":6,"question":"'வஞ்சி நெடும்பாட்டு' என்ற சிறப்புப் பெயர் பெற்ற பத்துப்பாட்டு நூல் எது?","options":["பெரும்பாணாற்றுப்படை","மலைபடுகடாம்","பட்டினப்பாலை","மதுரைக்காஞ்சி"],"correctAnswer":2,"explanation":"கடியலூர் உருத்திரங்கண்ணனார் இயற்றிய பட்டினப்பாலை 301 அடிகளைக் கொண்டது; இதில் வஞ்சி அடிகள் மிகுதியாகக் கலந்துள்ளதால் இதற்கு 'வஞ்சி நெடும்பாட்டு' என்ற சிறப்புப் பெயர் வழங்கப்படுகிறது. இதன் பாட்டுடைத் தலைவன் கரிகால் பெருவளத்தான் ஆவார்.","difficulty":"medium","topic":"பத்துப்பாட்டு – பட்டினப்பாலை"},{"id":565,"subject":"tamil","testNumber":6,"question":"\"கொள்வதூஉம் மிகை கொளாது கொடுப்பதூஉம் குறைபடாது\" என்று புகார் நகர வணிகர்களின் நேர்மையைப் பாராட்டும் நூல் எது?","options":["பெரும்பாணாற்றுப்படை","மதுரைக்காஞ்சி","பட்டினப்பாலை","பொருநராற்றுப்படை"],"correctAnswer":2,"explanation":"பட்டினப்பாலை காவிரிப்பூம்பட்டினம் (புகார்) நகரத்தின் வணிகச் சிறப்பைப் பாடுகிறது. பிறரிடமிருந்து மிகுதியாக வாங்காமலும், பிறருக்குக் குறைவாகக் கொடுக்காமலும் நடுவுநிலைமையோடு வணிகம் செய்த தமிழர் பண்பை இவ்வடிகள் விளக்குகின்றன.","difficulty":"medium","topic":"பத்துப்பாட்டு – பட்டினப்பாலை"},{"id":566,"subject":"tamil","testNumber":6,"question":"\"நீரின் வந்த நிமிர் பரிப் புரவியும் காலின் வந்த கருங்கறி மூடையும்\" என்ற புகழ்பெற்ற வணிக அடிகள் இடம்பெற்றுள்ள நூல் எது?","options":["மதுரைக்காஞ்சி","சிறுபாணாற்றுப்படை","பெரும்பாணாற்றுப்படை","பட்டினப்பாலை"],"correctAnswer":3,"explanation":"பட்டினப்பாலையில் இடம்பெற்றுள்ள இவ்வடிகள், கடல் வழியாகக் கப்பல்களில் வந்த குதிரைகளும், தரைவழியாக வண்டிகளில் வந்த கரிய மிளகு மூட்டைகளும் காவிரிப்பூம்பட்டினம் துறைமுகத்தில் குவிந்திருந்த ஏற்றுமதி-இறக்குமதி வளத்தைக் கூறுகின்றன.","difficulty":"hard","topic":"பத்துப்பாட்டு – பட்டினப்பாலை"},{"id":567,"subject":"tamil","testNumber":6,"question":"'கூத்தராற்றுப்படை' என்று அழைக்கப்படும் பத்துப்பாட்டு நூல் எது?","options":["சிறுபாணாற்றுப்படை","பொருநராற்றுப்படை","பெரும்பாணாற்றுப்படை","மலைபடுகடாம்"],"correctAnswer":3,"explanation":"583 அடிகளைக் கொண்ட மலைபடுகடாம் 'கூத்தராற்றுப்படை' என்றும் அழைக்கப்படுகிறது. பரிசில் பெற்ற கூத்தன் ஒருவன், பரிசில் பெற விரும்பும் மற்றொரு கூத்தனை நன்னன் சேய் நன்னனிடம் ஆற்றுப்படுத்துவதாக இந்நூல் அமைந்துள்ளது.","difficulty":"easy","topic":"பத்துப்பாட்டு – மலைபடுகடாம்"},{"id":568,"subject":"tamil","testNumber":6,"question":"மலைபடுகடாம் நூலின் ஆசிரியர் மற்றும் பாட்டுடைத் தலைவர் முறையே யாவர்?","options":["பெருங்கௌசிகனார், நன்னன் சேய் நன்னன்","நல்லூர் நத்தத்தனார், நல்லியக்கோடன்","மாங்குடி மருதனார், பாண்டியன் நெடுஞ்செழியன்","முடத்தாமக்கண்ணியார், கரிகால் பெருவளத்தான்"],"correctAnswer":0,"explanation":"மலைபடுகடாமை இயற்றியவர் இரணியமுட்டத்துப் பெருங்குன்றூர் பெருங்கௌசிகனார் ஆவார். இதன் பாட்டுடைத் தலைவன் பல்குன்றக் கோட்டத்துச் செங்கண்மாத்து வேள் நன்னன் சேய் நன்னன் ஆவார்.","difficulty":"medium","topic":"பத்துப்பாட்டு – மலைபடுகடாம்"},{"id":569,"subject":"tamil","testNumber":6,"question":"'மலைபடுகடாம்' என்ற நூலின் பெயரில் 'கடாம்' என்பது எதனை உருவகமாகக் குறிக்கிறது?","options":["யானையின் மதத்தை (மலையில் எழும் ஓசைகளை)","மலையின் உயரத்தை","மலையில் விளையும் தேனை","மலையில் விழும் அருவியை"],"correctAnswer":0,"explanation":"மலையை யானையாகவும், அந்த மலையில் அருவி, பறவை, விலங்கு, இசைக்கருவிகள் ஆகியவற்றால் எழும் பலவகை ஓசைகளை யானையின் மதமாகவும் (கடாம்) கற்பனை செய்து உருவகம் செய்ததால் இந்நூல் 'மலைபடுகடாம்' எனப் பெயர் பெற்றது.","difficulty":"hard","topic":"பத்துப்பாட்டு – மலைபடுகடாம்"},{"id":570,"subject":"tamil","testNumber":6,"question":"பத்துப்பாட்டுத் தொகுப்பில் தலா இரண்டு நூல்களை இயற்றிய சங்கப் புலவர்கள் யாவர்?","options":["நப்பூதனார் மற்றும் பெருங்கௌசிகனார்","நக்கீரர் மற்றும் கடியலூர் உருத்திரங்கண்ணனார்","கபிலர் மற்றும் மாங்குடி மருதனார்","முடத்தாமக்கண்ணியார் மற்றும் நல்லூர் நத்தத்தனார்"],"correctAnswer":1,"explanation":"பத்துப்பாட்டில் நக்கீரர் திருமுருகாற்றுப்படை, நெடுநல்வாடை ஆகிய இரு நூல்களையும்; கடியலூர் உருத்திரங்கண்ணனார் பெரும்பாணாற்றுப்படை, பட்டினப்பாலை ஆகிய இரு நூல்களையும் இயற்றியுள்ளனர். இவ்வாறு 8 புலவர்கள் சேர்ந்து 10 நூல்களைப் பாடியுள்ளனர்.","difficulty":"hard","topic":"பத்துப்பாட்டு – பொது அறிமுகம்"},{"id":571,"subject":"tamil","testNumber":6,"question":"பதினெண்கீழ்க்கணக்கு நூல்களில் உள்ள அறநூல்கள், அகநூல்கள் மற்றும் புறநூலின் எண்ணிக்கை முறையே எவ்வளவு?","options":["9 அறநூல்கள், 7 அகநூல்கள், 2 புறநூல்கள்","11 அறநூல்கள், 6 அகநூல்கள், 1 புறநூல்","10 அறநூல்கள், 6 அகநூல்கள், 2 புறநூல்கள்","12 அறநூல்கள், 5 அகநூல்கள், 1 புறநூல்"],"correctAnswer":1,"explanation":"பதினெண்கீழ்க்கணக்கு எனப்படும் 18 நூல்களுள் அறநூல்கள் 11, அகப்பொருள் நூல்கள் 6 (கார் நாற்பது, ஐந்திணை ஐம்பது, ஐந்திணை எழுபது, திணைமொழி ஐம்பது, திணைமாலை நூற்றைம்பது, கைந்நிலை) மற்றும் புறப்பொருள் நூல் 1 (களவழி நாற்பது) ஆகும்.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – பொது அறிமுகம்"},{"id":572,"subject":"tamil","testNumber":6,"question":"'வேளாண் வேதம்' என்று சிறப்பிக்கப்படும் பதினெண்கீழ்க்கணக்கு அறநூல் எது?","options":["பழமொழி நானூறு","ஏலாதி","ஆசாரக்கோவை","நாலடியார்"],"correctAnswer":3,"explanation":"சமண முனிவர்கள் பலர் பாடிய 400 வெண்பாக்களைக் கொண்ட நாலடியார் 'வேளாண் வேதம்' மற்றும் 'நாலடி நானூறு' என்ற சிறப்புப் பெயர்களால் அழைக்கப்படுகிறது. இதனை ஜி.யு. போப் ஆங்கிலத்தில் மொழிபெயர்த்துள்ளார்.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – நாலடியார்"},{"id":573,"subject":"tamil","testNumber":6,"question":"சமண முனிவர்கள் பாடிய நாலடியார் பாடல்களைத் தொகுத்து முப்பாலாகப் பகுத்தவர் யார்?","options":["முன்றுறையரையனார்","கணிமேதாவியார்","பதுமனார்","விளம்பிநாகனார்"],"correctAnswer":2,"explanation":"சமண முனிவர்கள் இயற்றிய 400 வெண்பாக்களைத் தொகுத்து, அறத்துப்பால், பொருட்பால், காமத்துப்பால் என முப்பாலாகப் பகுத்து நாலடியாரை ஒழுங்குபடுத்தியவர் பதுமனார் ஆவார்.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – நாலடியார்"},{"id":574,"subject":"tamil","testNumber":6,"question":"\"கல்வி கரையில கற்பவர் நாள்சில\" என்ற புகழ்பெற்ற கல்விச் சிறப்பு வரி இடம்பெற்றுள்ள அறநூல் எது?","options":["சிறுபஞ்சமூலம்","நாலடியார்","திரிகடுகம்","நான்மணிக்கடிகை"],"correctAnswer":1,"explanation":"இவ்வரி நாலடியாரின் கல்வி அதிகாரத்தில் இடம்பெற்றுள்ளது. கற்க வேண்டிய கல்விக்கு எல்லையில்லை, கற்பவரின் வாழ்நாளோ மிகக் குறைவு; எனவே அன்னம் பாலை மட்டும் பிரித்து உண்பது போல் நல்ல நூல்களைத் தேர்ந்தெடுத்துக் கற்க வேண்டும் என இப்பாடல் அறிவுறுத்துகிறது.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – நாலடியார்"},{"id":575,"subject":"tamil","testNumber":6,"question":"\"வைப்புழிக் கோட்படா வாய்த்தீயிற் கேடில்லை\" என்று அழியாத கல்விச் செல்வத்தின் மேன்மையைக் கூறும் நூல் எது?","options":["முதுமொழிக்காஞ்சி","பழமொழி நானூறு","ஆசாரக்கோவை","நாலடியார்"],"correctAnswer":3,"explanation":"நாலடியாரில் இடம்பெறும் இப்பாடல், கல்வியானது பிறரால் கவரப்படாது, நெருப்பாலும் அழியாது, மன்னராலும் பறிக்கப்படாது என்பதால் எச்செல்வத்தை விடவும் கல்விச் செல்வமே உயர்ந்தது என்பதை விளக்குகிறது.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – நாலடியார்"},{"id":576,"subject":"tamil","testNumber":6,"question":"ஒவ்வொரு பாடலிலும் நான்கு உயர்ந்த அறக்கருத்துகளை மணிகளைப் போல் கோத்துக் கூறும் 'நான்மணிக்கடிகை' நூலின் ஆசிரியர் யார்?","options":["நல்லாதனார்","காரியாசான்","பூதஞ்சேந்தனார்","விளம்பிநாகனார்"],"correctAnswer":3,"explanation":"நான்மணிக்கடிகையை இயற்றியவர் விளம்பிநாகனார் ஆவார். 'விளம்பி' என்பது ஊர்ப்பெயர்; 'நாகனார்' என்பது இயற்பெயர். 'கடிகை' என்றால் துண்டு அல்லது அணிகலன் எனப் பொருள்படும்.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – நான்மணிக்கடிகை"},{"id":577,"subject":"tamil","testNumber":6,"question":"\"மனைக்கு விளக்கம் மடவாள் மடவாள் தனக்குத் தகைசால் புதல்வர்\" என்ற புகழ்பெற்ற அடிகள் இடம்பெற்றுள்ள நூல் எது?","options":["நாலடியார்","நான்மணிக்கடிகை","ஏலாதி","இனியவை நாற்பது"],"correctAnswer":1,"explanation":"விளம்பிநாகனார் இயற்றிய நான்மணிக்கடிகையில் இவ்வடிகள் இடம்பெற்றுள்ளன. இல்லத்திற்கு விளக்குப் போன்றவள் பெண், அவளுக்கு விளக்குப் போன்றவர் நற்பண்புடைய மக்கள், அம்மக்களுக்கு விளக்குப் போன்றது கல்வி, அக்கல்விக்கு விளக்குப் போன்றது நல்லெண்ணம் என நான்கு அறங்களை இப்பாடல் கூறுகிறது.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – நான்மணிக்கடிகை"},{"id":578,"subject":"tamil","testNumber":6,"question":"பதினெண்கீழ்க்கணக்கு நூல்களுள் 'இரட்டை அறநூல்கள்' என்று அழைக்கப்படுபவை எவை?","options":["திரிகடுகம் மற்றும் ஏலாதி","ஐந்திணை ஐம்பது மற்றும் ஐந்திணை எழுபது","கார் நாற்பது மற்றும் களவழி நாற்பது","இன்னா நாற்பது மற்றும் இனியவை நாற்பது"],"correctAnswer":3,"explanation":"துன்பம் தரும் செயல்களைக் கூறும் 'இன்னா நாற்பது' மற்றும் இன்பம் தரும் செயல்களைக் கூறும் 'இனியவை நாற்பது' ஆகிய இரண்டும் ஒன்றுக்கொன்று இணையான அறநூல்களாக விளங்குவதால் 'இரட்டை அறநூல்கள்' என அழைக்கப்படுகின்றன.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – இன்னா, இனியவை நாற்பது"},{"id":579,"subject":"tamil","testNumber":6,"question":"உலகில் துன்பம் தரும் செயல்களைத் தொகுத்துக் கூறும் 40 வெண்பாக்களைக் கொண்ட 'இன்னா நாற்பது' நூலின் ஆசிரியர் யார்?","options":["பொய்கையார்","பூதஞ்சேந்தனார்","கபிலர்","மதுரைக் கண்ணங்கூத்தனார்"],"correctAnswer":2,"explanation":"இன்னா நாற்பது நூலின் ஆசிரியர் கபிலர் ஆவார். கடவுள் வாழ்த்து நீங்கலாக 40 வெண்பாக்களைக் கொண்ட இந்நூலில் 164 துன்பம் தரும் (இன்னாத) செய்திகள் தொகுத்துக் கூறப்பட்டுள்ளன.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – இன்னா நாற்பது"},{"id":580,"subject":"tamil","testNumber":6,"question":"\"கற்றார் முன் கல்வி உரைத்தல் மிக இனிதே\" என்ற வரி இடம்பெற்றுள்ள இனியவை நாற்பதை இயற்றியவர் யார்?","options":["பூதஞ்சேந்தனார்","விளம்பிநாகனார்","கபிலர்","நல்லாதனார்"],"correctAnswer":0,"explanation":"மதுரைத் தமிழாசிரியர் மகனார் பூதஞ்சேந்தனார் இனியவை நாற்பதை இயற்றியுள்ளார். கடவுள் வாழ்த்து நீங்கலாக 40 வெண்பாக்களைக் கொண்ட இந்நூலில் 'குழவி பிணியின்றி வாழ்தல் இனிதே', 'கற்றார் முன் கல்வி உரைத்தல் மிக இனிதே' போன்ற இனிய அறக்கருத்துகள் உள்ளன.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – இனியவை நாற்பது"},{"id":581,"subject":"tamil","testNumber":6,"question":"பதினெண்கீழ்க்கணக்கில் முல்லைத் திணைக்குரிய கார்கால வருணனையை மட்டும் பாடும் அகநூலான 'கார் நாற்பது' இயற்றியவர் யார்?","options":["பொய்கையார்","புல்லங்காடனார்","மதுரைக் கண்ணங்கூத்தனார்","மாறன் பொறையனார்"],"correctAnswer":2,"explanation":"கார் நாற்பதை இயற்றியவர் மதுரைக் கண்ணங்கூத்தனார் ஆவார். பதினெண்கீழ்க்கணக்கில் உள்ள ஆறு அகநூல்களுள் மிகச் சிறிய நூலான இது 40 வெண்பாக்களைக் கொண்டுள்ளது; திருக்கார்த்திகை விளக்கீடு பற்றிக் குறிப்பிடும் சிறப்பும் இதற்கு உண்டு.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – கார் நாற்பது"},{"id":582,"subject":"tamil","testNumber":6,"question":"பதினெண்கீழ்க்கணக்கு நூல்களுள் இடம்பெற்றுள்ள ஒரே புறப்பொருள் நூல் எது?","options":["களவழி நாற்பது","கைந்நிலை","முதுமொழிக்காஞ்சி","கார் நாற்பது"],"correctAnswer":0,"explanation":"பதினெண்கீழ்க்கணக்கு நூல்கள் 18-இல் களவழி நாற்பது மட்டுமே புறப்பொருள் நூலாகும். பொய்கையார் இயற்றிய இந்நூல் கழுமலப் போர்க்களச் சிறப்பை 40 வெண்பாக்களில் பாடுகிறது.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – களவழி நாற்பது"},{"id":583,"subject":"tamil","testNumber":6,"question":"பொய்கையார் களவழி நாற்பதைப் பாடி சோழன் செங்கணானின் சிறையிலிருந்து எந்தச் சேர மன்னனை விடுவித்தார்?","options":["செல்வக்கடுங்கோ வாழியாதன்","யானைக்கட்சேய் மாந்தரஞ்சேரல்","இமயவரம்பன் நெடுஞ்சேரலாதன்","சேரமான் கணைக்கால் இரும்பொறை"],"correctAnswer":3,"explanation":"கழுமலப் போரில் சோழன் செங்கணானால் சிறைப்பிடிக்கப்பட்ட தன் நண்பரான சேரமான் கணைக்கால் இரும்பொறையை விடுவிப்பதற்காகப் பொய்கையார் சோழனின் போர் வெற்றியைப் புகழ்ந்து களவழி நாற்பதைப் பாடினார்.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – களவழி நாற்பது"},{"id":584,"subject":"tamil","testNumber":6,"question":"தமிழ் இலக்கிய வரலாற்றில் பிற்காலப் 'பரணி' இலக்கியத்திற்கு முன்னோடியாக விளங்கும் பதினெண்கீழ்க்கணக்கு நூல் எது?","options":["முதுமொழிக்காஞ்சி","கார் நாற்பது","களவழி நாற்பது","பழமொழி நானூறு"],"correctAnswer":2,"explanation":"போர்க்களத்தில் யானைகள் வீழ்ந்த காட்சியையும் வீரர்களின் போர்ச்சிறப்பையும் பாடும் களவழி நாற்பது, பிற்காலத்தில் தோன்றிய கலிங்கத்துப்பரணி போன்ற பரணி சிற்றிலக்கியங்களுக்கு முன்னோடியாகத் திகழ்கிறது.","difficulty":"hard","topic":"பதினெண்கீழ்க்கணக்கு – களவழி நாற்பது"},{"id":585,"subject":"tamil","testNumber":6,"question":"\"ஐந்திணை ஐம்பதும் ஆர்வத்தின் ஓதாதார் செந்தமிழ் சேராதவர்\" எனச் சிறப்புப் பாயிரம் போற்றும் ஐந்திணை ஐம்பதை இயற்றியவர் யார்?","options":["புல்லங்காடனார்","மூவாதியார்","மாறன் பொறையனார்","கண்ணன் சேந்தனார்"],"correctAnswer":2,"explanation":"ஐந்திணை ஐம்பதை இயற்றியவர் மாறன் பொறையனார் ஆவார். முல்லை, குறிஞ்சி, மருதம், பாலை, நெய்தல் ஆகிய ஐந்து திணைகளுக்கும் திணைக்கு 10 பாடல்கள் வீதம் 50 வெண்பாக்களைக் கொண்ட அழகிய அகநூலாகும்.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – ஐந்திணை ஐம்பது"},{"id":586,"subject":"tamil","testNumber":6,"question":"விநாயகர் கடவுள் வாழ்த்து இடம்பெற்றுள்ளதாகக் கருதப்படும் 'ஐந்திணை எழுபது' என்ற அகநூலை இயற்றியவர் யார்?","options":["மூவாதியார்","கணிமேதாவியார்","மாறன் பொறையனார்","கண்ணன் சேந்தனார்"],"correctAnswer":0,"explanation":"ஐந்திணை எழுபதை இயற்றியவர் மூவாதியார் ஆவார். ஐந்து திணைகளுக்கும் திணைக்கு 14 பாடல்கள் வீதம் 70 பாடல்களைக் கொண்ட இந்நூலில் தற்போது 66 பாடல்கள் முழுமையாகக் கிடைத்துள்ளன.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – ஐந்திணை எழுபது"},{"id":587,"subject":"tamil","testNumber":6,"question":"'திணைமொழி ஐம்பது' என்ற பதினெண்கீழ்க்கணக்கு அகநூலை இயற்றிய புலவர் யார்?","options":["மாறன் பொறையனார்","கண்ணன் சேந்தனார்","மதுரைக் கண்ணங்கூத்தனார்","புல்லங்காடனார்"],"correctAnswer":1,"explanation":"திணைமொழி ஐம்பதை இயற்றியவர் சாத்தந்தையார் மகனார் கண்ணன் சேந்தனார் ஆவார். குறிஞ்சி, பாலை, முல்லை, மருதம், நெய்தல் ஆகிய ஐந்து திணைகளுக்கும் திணைக்கு 10 வெண்பாக்கள் வீதம் 50 பாடல்கள் இதில் அமைந்துள்ளன.","difficulty":"hard","topic":"பதினெண்கீழ்க்கணக்கு – திணைமொழி ஐம்பது"},{"id":588,"subject":"tamil","testNumber":6,"question":"பதினெண்கீழ்க்கணக்கு அகநூல்களுள் மிக அதிக பாடல்களைக் கொண்ட 'திணைமாலை நூற்றைம்பது' இயற்றியவர் யார்?","options":["கணிமேதாவியார்","மூவாதியார்","காரியாசான்","நல்லாதனார்"],"correctAnswer":0,"explanation":"திணைமாலை நூற்றைம்பதை இயற்றியவர் சமண சமயத்தவரான கணிமேதாவியார் ஆவார்; ஏலாதி என்ற அறநூலையும் இவரே இயற்றியுள்ளார். ஐந்து திணைகளுக்கும் தலா 30 பாடல்கள் வீதம் அமைந்த இந்நூல் பதினெண்கீழ்க்கணக்கு அகநூல்களுள் மிகப் பெரியதாகும்.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – திணைமாலை நூற்றைம்பது"},{"id":589,"subject":"tamil","testNumber":6,"question":"பதினெண்கீழ்க்கணக்கு நூல்களுள் சித்த மருத்துவ மருந்துப் பெயர்களைக் கொண்ட மூன்று அறநூல்கள் எவை?","options":["பழமொழி நானூறு, முதுமொழிக்காஞ்சி, ஏலாதி","இன்னா நாற்பது, இனியவை நாற்பது, திரிகடுகம்","திரிகடுகம், சிறுபஞ்சமூலம், ஏலாதி","நாலடியார், நான்மணிக்கடிகை, ஆசாரக்கோவை"],"correctAnswer":2,"explanation":"திரிகடுகம் (3 மருந்துப் பொருட்கள்), சிறுபஞ்சமூலம் (5 வேர்கள்), ஏலாதி (6 மருந்துப் பொருட்கள்) ஆகிய மூன்றும் உடல் நோயைத் தீர்க்கும் மருந்துகளின் பெயரால் அமைந்து, உள்ளத்தின் அறியாமை நோயைத் தீர்க்கும் அறநூல்களாக விளங்குகின்றன.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – மருந்துப் பெயர் நூல்கள்"},{"id":590,"subject":"tamil","testNumber":6,"question":"திரிகடுகம் என்ற நூலின் ஆசிரியர் மற்றும் அம்மருந்தில் அடங்கும் மூன்று பொருட்கள் முறையே எவை?","options":["பெருவாயின் முள்ளியார்; சுக்கு, ஏலம், மிளகு","நல்லாதனார்; சுக்கு, மிளகு, திப்பிலி","காரியாசான்; மிளகு, நெருஞ்சி, திப்பிலி","கணிமேதாவியார்; ஏலம், இலவங்கம், சுக்கு"],"correctAnswer":1,"explanation":"திரிகடுகத்தை இயற்றியவர் திருத்து என்ற ஊரைச் சேர்ந்த நல்லாதனார் ('செருஅடு தோள் நல்லாதன்') ஆவார். சுக்கு, மிளகு, திப்பிலி என்ற மூன்று காரப் பொருட்கள் உடல் நோய் தீர்ப்பது போல், இந்நூலின் 100 வெண்பாக்களும் பாடலுக்கு மூன்று அறக்கருத்துகளைக் கூறுகின்றன.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – திரிகடுகம்"},{"id":591,"subject":"tamil","testNumber":6,"question":"ஆசாரக்கோவையை இயற்றிய பெருவாயின் முள்ளியார் குறிப்பிடும் 'ஆசார வித்து' (நல்லொழுக்கத்தின் விதை) எத்தனை நற்பண்புகளைக் கொண்டது?","options":["ஐந்து நற்பண்புகள்","ஆறு நற்பண்புகள்","பத்து நற்பண்புகள்","எட்டு நற்பண்புகள்"],"correctAnswer":3,"explanation":"ஆசாரக்கோவை 100 வெண்பாக்களைக் கொண்ட நல்லொழுக்க நூலாகும். இதில் நன்றி அறிதல், பொறையுடைமை, இன்சொல், எவ்வுயிர்க்கும் தீங்கு செய்யாமை, கல்வி, ஒப்புரவு, அறிவுடைமை, நல்லினத்தாரோடு நட்பு ஆகிய எட்டு குணங்களும் நல்லொழுக்கத்தின் விதை (ஆசார வித்து) எனக் கூறப்பட்டுள்ளன.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – ஆசாரக்கோவை"},{"id":592,"subject":"tamil","testNumber":6,"question":"\"நன்றி அறிதல் பொறையுடைமை இன்சொல்லோடு... சொல்லிய ஆசார வித்து\" என்ற புகழ்பெற்ற பாடல் இடம்பெற்றுள்ள நூல் எது?","options":["ஆசாரக்கோவை","சிறுபஞ்சமூலம்","நாலடியார்","முதுமொழிக்காஞ்சி"],"correctAnswer":0,"explanation":"இப்பாடல் கயத்தூரைச் சேர்ந்த பெருவாயின் முள்ளியார் இயற்றிய ஆசாரக்கோவையில் இடம்பெற்றுள்ளது. 'ஆசாரம்' என்பது நல்லொழுக்கத்தையும், 'கோவை' என்பது அடுக்கிச் சொல்லுதலையும் குறிக்கும்.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – ஆசாரக்கோவை"},{"id":593,"subject":"tamil","testNumber":6,"question":"ஒவ்வொரு பாடலின் இறுதியிலும் ஒரு பழமொழியை அமைத்து 'பழமொழி நானூறு' என்ற அறநூலை இயற்றியவர் யார்?","options":["முன்றுறையரையனார்","பதுமனார்","மதுரைக் கூடலூர் கிழார்","விளம்பிநாகனார்"],"correctAnswer":0,"explanation":"பழமொழி நானூற்றை இயற்றியவர் முன்றுறையரையனார் என்ற சமண சமயப் புலவர் ஆவார். 400 வெண்பாக்களைக் கொண்ட இந்நூலின் ஒவ்வொரு பாடலின் ஈற்றடியிலும் ஒரு பழமொழி அமைந்திருப்பது தனிச்சிறப்பாகும்.","difficulty":"easy","topic":"பதினெண்கீழ்க்கணக்கு – பழமொழி நானூறு"},{"id":594,"subject":"tamil","testNumber":6,"question":"\"ஆற்றவும் கற்றார் அறிவுடையார்... ஆற்றுணா வேண்டுவது இல்\" என்ற பழமொழி நானூற்றுப் பாடலில் 'ஆற்றுணா' என்பதன் பொருள் என்ன?","options":["துணைவன்","பயணச் செலவு","ஆற்று நீர்","வழிநடை உணவு (கட்டுச்சோறு)"],"correctAnswer":3,"explanation":"'ஆறு + உணா = ஆற்றுணா' என்பதற்கு வழிநடை உணவு (கட்டுச்சோறு) என்று பொருள். நிரம்பக் கற்றறிந்த அறிவுடையோர் எந்த நாட்டிற்குச் சென்றாலும் அது தம் நாடாகவே போற்றப்படுவர்; ஆதலால் அவர்களுக்கு வழியுணவாகிய கட்டுச்சோறு தேவையில்லை என்பது இப்பாடலின் கருத்தாகும்.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – பழமொழி நானூறு"},{"id":595,"subject":"tamil","testNumber":6,"question":"மதுரைத் தமிழாசிரியர் மாக்காயனாரின் மாணாக்கரும், 'சிறுபஞ்சமூலம்' என்ற அறநூலின் ஆசிரியருமான புலவர் யார்?","options":["காரியாசான்","பெருவாயின் முள்ளியார்","கணிமேதாவியார்","நல்லாதனார்"],"correctAnswer":0,"explanation":"சிறுபஞ்சமூலத்தை இயற்றியவர் சமண சமயத்தவரான காரியாசான் ('மாக்காரியாசான்') ஆவார். காரியாசானும் ஏலாதி இயற்றிய கணிமேதாவியாரும் மதுரைத் தமிழாசிரியர் மாக்காயனாரின் ஒருசாலை மாணாக்கர்கள் ஆவர்.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – சிறுபஞ்சமூலம்"},{"id":596,"subject":"tamil","testNumber":6,"question":"\"பூவாது காய்க்கும் மரமுள நன்றறிவார் மூவாது மூத்தவர் நூல்வல்லார்\" என்ற புகழ்பெற்ற வெண்பா இடம்பெற்றுள்ள நூல் எது?","options":["பழமொழி நானூறு","நாலடியார்","சிறுபஞ்சமூலம்","திரிகடுகம்"],"correctAnswer":2,"explanation":"காரியாசான் இயற்றிய சிறுபஞ்சமூலத்தில் இப்பாடல் இடம்பெற்றுள்ளது. பூக்காமல் காய்க்கும் மரங்கள் இருப்பது போலவும், விதைக்காமல் முளைக்கும் விதைகள் இருப்பது போலவும், அறிவுடையோர் இளமையிலேயே முதிர்ந்த ஞானம் பெற்றவராக விளங்குவர் என்பதை இப்பாடல் விளக்குகிறது.","difficulty":"hard","topic":"பதினெண்கீழ்க்கணக்கு – சிறுபஞ்சமூலம்"},{"id":597,"subject":"tamil","testNumber":6,"question":"'சிறுபஞ்சமூலம்' என்ற மருந்துப் பெயர் குறிக்கும் ஐந்து வேர்கள் யாவை?","options":["துளசி, தூதுவளை, கரிசலாங்கண்ணி, கீழாநெல்லி, முசுமுசுக்கை","வேம்பு, ஆலம், அரசு, நாவல், நெல்லி","சுக்கு, மிளகு, திப்பிலி, ஏலம், இலவங்கம்","கண்டங்கத்திரி, சிறுவழுதுணை, சிறுமல்லி, பெருமல்லி, நெருஞ்சி"],"correctAnswer":3,"explanation":"கண்டங்கத்திரி, சிறுவழுதுணை, சிறுமல்லி, பெருமல்லி, நெருஞ்சி ஆகிய ஐந்து சிறிய வேர்களால் ஆன மருந்து 'சிறுபஞ்சமூலம்' எனப்படும். இம்மருந்து உடல் நோயைத் தீர்ப்பது போல இந்நூலின் ஒவ்வொரு பாடலிலும் உள்ள ஐந்து அறக்கருத்துகள் மக்களின் அறியாமையைப் போக்குகின்றன.","difficulty":"hard","topic":"பதினெண்கீழ்க்கணக்கு – சிறுபஞ்சமூலம்"},{"id":598,"subject":"tamil","testNumber":6,"question":"'அறவுரைக்கோவை' என்ற சிறப்புப் பெயர் கொண்ட 'முதுமொழிக்காஞ்சி' என்ற நூலை இயற்றியவர் யார்?","options":["பெருவாயின் முள்ளியார்","பூதஞ்சேந்தனார்","விளம்பிநாகனார்","மதுரைக் கூடலூர் கிழார்"],"correctAnswer":3,"explanation":"முதுமொழிக்காஞ்சியை இயற்றியவர் மதுரைக் கூடலூர் கிழார் ஆவார். 10 அதிகாரங்களும் அதிகாரத்திற்கு 10 குறட்டாழிசைகள் (ஒற்றை அடிகள்) வீதம் 100 பாடல்களும் கொண்ட இந்நூல் 'அறவுரைக்கோவை' எனப் போற்றப்படுகிறது. இதன் முதல் அதிகாரம் 'சிறந்த பத்து' ஆகும்.","difficulty":"medium","topic":"பதினெண்கீழ்க்கணக்கு – முதுமொழிக்காஞ்சி"},{"id":599,"subject":"tamil","testNumber":6,"question":"கணிமேதாவியார் இயற்றிய 'ஏலாதி' நூலின் ஒவ்வொரு பாடலிலும் கூறப்படும் அறக்கருத்துகளின் எண்ணிக்கை மற்றும் அம்மருந்தில் அடங்கும் ஆறு பொருட்கள் யாவை?","options":["நான்கு அறக்கருத்துகள்; ஏலம், மஞ்சள், சுக்கு, மிளகு, திப்பிலி, நெல்லி","ஆறு அறக்கருத்துகள்; ஏலம், துளசி, சிறுமல்லி, சுக்கு, மிளகு, திப்பிலி","ஆறு அறக்கருத்துகள்; ஏலம், இலவங்கம், சிறுநாவற்பூ, சுக்கு, மிளகு, திப்பிலி","ஐந்து அறக்கருத்துகள்; ஏலம், இலவங்கம், வேம்பு, சுக்கு, மிளகு, நெருஞ்சி"],"correctAnswer":2,"explanation":"ஏலாதி 80 வெண்பாக்களைக் கொண்ட அறநூலாகும். ஏலத்தை முதலாகக் கொண்ட ஏலம், இலவங்கம், சிறுநாவற்பூ, சுக்கு, மிளகு, திப்பிலி ஆகிய ஆறு மருந்துப் பொருட்களால் ஆன 'ஏலாதி' சூரணம் போல், இந்நூலின் ஒவ்வொரு பாடலிலும் ஆறு அறக்கருத்துகள் இடம்பெற்றுள்ளன.","difficulty":"hard","topic":"பதினெண்கீழ்க்கணக்கு – ஏலாதி"},{"id":600,"subject":"tamil","testNumber":6,"question":"'ஐந்திணை அறுபது' என்றும் அழைக்கப்படும் 'கைந்நிலை' என்ற பதினெண்கீழ்க்கணக்கு அகநூலை இயற்றியவர் யார்?","options":["மூவாதியார்","மாறன் பொறையனார்","கண்ணன் சேந்தனார்","புல்லங்காடனார்"],"correctAnswer":3,"explanation":"கைந்நிலையை இயற்றியவர் மாறோக்கத்து முள்ளிநாட்டு நல்லூர்க் காவிதியார் மகனார் புல்லங்காடனார் ஆவார். 'கை' என்றால் ஒழுக்கம்; ஐந்து திணைகளுக்கும் திணைக்கு 12 பாடல்கள் வீதம் 60 வெண்பாக்களில் ஐந்திணை ஒழுக்க நிலைகளைக் கூறுவதால் இதற்குக் 'கைந்நிலை' ('ஐந்திணை அறுபது') எனப் பெயர் ஏற்பட்டது.","difficulty":"hard","topic":"பதினெண்கீழ்க்கணக்கு – கைந்நிலை"}]);
